	uint256 index = indexAtTimestamp(e.block.timestamp);
	uint256 balanceBeforeUser = balanceOf(e, u);
	uint256 totalSupplyBefore = totalSupply(); 

	burn(e, u, amount, index);

	uint256 balanceAfterUser = balanceOf(e, u);
